SHA256 = "aa85416b3e52ab9e1fe2dad3075de9a483c3334ce3579b6a420cf7bc328c32fe"

root = Path(__file__).resolve().parents[1]
try:
    patch = lzma.decompress(base64.b64decode("".join(DATA.split()), validate=True))
except Exception:
    raise SystemExit("更新內容不完整，請重新完整複製程式。尚未修改任何檔案。")
if hashlib.sha256(patch).hexdigest() != SHA256:
    raise SystemExit("更新內容檢查未通過，尚未修改任何檔案。")

def run(*args):
    return subprocess.run(
        ["git", "apply", "--whitespace=nowarn", *args, "-"],
        input=patch, cwd=root, capture_output=True
    )

check = run("--check")
if check.returncode:
    if run("--reverse", "--check").returncode == 0:
        print("日曆更新已套用，不需重複修改。")
    else:
        print(check.stderr.decode("utf-8", errors="replace"))
        raise SystemExit("目前程式版本有差異，未強制覆蓋。請提供這段錯誤以調整更新程式。")
else:
    result = run()
    if result.returncode:
        print(result.stderr.decode("utf-8", errors="replace"))
        raise SystemExit("更新未完成，請提供錯誤訊息。")
    print("日曆功能已加入。接著請部署 Firestore 規則與 notifications Cloud Functions。")
